      return { out: computed(() => a.value + b.value), write: (i) => { a.value = i; } };
    }),
    write: (instance, i) => { instance.a.value = i; },
  },
  {
    name: 'medium',
    getter: new (Reactive($MediumGetter))(),
    ivueComputed: new (Reactive($MediumComputed))(),
